package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.dto.Requests.RiskRuleRequest;import com.example.riskplatform.entity.RiskRule;import com.example.riskplatform.mapper.RiskRuleMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class RiskRuleService{private final RiskRuleMapper mapper;private final AuditService audit;private final CorpusEvents corpus;public List<RiskRule>list(){return mapper.selectList(new LambdaQueryWrapper<RiskRule>().orderByDesc(RiskRule::getId));}public RiskRule create(RiskRuleRequest r){RiskRule x=new RiskRule();BeanUtils.copyProperties(r,x);mapper.insert(x);corpus.upsert("rule",x.getId(),null);audit.log("CREATE","RISK_RULE",x.getId(),x.getRuleName());return x;}public RiskRule update(Long id,RiskRuleRequest r){RiskRule x=new RiskRule();BeanUtils.copyProperties(r,x);x.setId(id);mapper.updateById(x);corpus.upsert("rule",id,null);audit.log("UPDATE","RISK_RULE",id,r.getRuleName());return mapper.selectById(id);}public void delete(Long id){mapper.deleteById(id);corpus.remove("rule",id,null);audit.log("DELETE","RISK_RULE",id,"delete");}}
